package in.prardhana.app;

import android.app.*;
import android.content.*;
import android.widget.*;
import org.json.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.concurrent.*;

/** Small, reviewable actions shared by Overview, Settings and the conversation. */
final class CoachUi {
    final PaynotesUi ui; final MainActivity a;
    private static final ExecutorService READ=Executors.newSingleThreadExecutor();
    CoachUi(PaynotesUi ui){this.ui=ui;a=ui.a;}
    interface Loaded {void run(CoachStore.Snapshot s);}
    void load(Loaded done){READ.execute(()->{try{var s=CoachStore.snapshot(LedgerDb.get(a),LocalDate.now());a.runOnUiThread(()->{if(!a.isDestroyed())done.run(s);});}catch(Exception e){a.runOnUiThread(()->toast("Couldn't load your plan. Please try again."));}});}
    void toast(String s){Toast.makeText(a,s,Toast.LENGTH_LONG).show();}
    LinearLayout box(){LinearLayout b=ui.column();b.setPadding(ui.dp(24),ui.dp(12),ui.dp(24),ui.dp(16));return b;}
    EditText field(LinearLayout b,String title,String value,boolean numeric){b.addView(ui.text(title,14,PaynotesUi.INK,true));EditText e=new EditText(a);e.setText(value);e.setTextSize(16);e.setSingleLine(true);e.setContentDescription(title);e.setInputType(numeric?android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL:android.text.InputType.TYPE_CLASS_TEXT);e.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(numeric?16:100)});b.addView(e);ui.gap(b,10);return e;}
    AlertDialog dialog(String title,LinearLayout b,String button,Runnable run){ScrollView scroll=new ScrollView(a);scroll.addView(b);AlertDialog d=new AlertDialog.Builder(a).setTitle(title).setView(scroll).setPositiveButton(button,null).setNegativeButton("Cancel",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{run.run();}catch(Exception e){toast(e.getMessage()==null?"Check the values and try again.":e.getMessage());}}));d.show();return d;}
    void save(JSONObject before,JSONObject next,String summary,Runnable close){
        new AlertDialog.Builder(a).setTitle("Review your change").setMessage(summary+"\n\nThis changes your local plan. It does not move money.").setPositiveButton("Confirm",(d,w)->{
            a.mutateLedger(()->{LedgerDb db=LedgerDb.get(a);if(!CoachStore.load(db).toString().equals(before.toString()))throw new IllegalStateException("Plan changed; reopen and retry");
                JSONObject value=LedgerDb.object(next.toString());try{JSONObject previous=LedgerDb.object(before.toString());previous.remove("undo");value.put("undo",previous);}catch(JSONException e){throw new IllegalStateException(e);}CoachStore.save(db,value);});close.run();
        }).setNegativeButton("Keep editing",null).show();
    }
    void card(LinearLayout parent){
        LinearLayout card=box();card.setBackground(ui.bg(PaynotesUi.PALE,18));parent.addView(card);ui.gap(parent,18);
        card.addView(ui.text("Your payday plan",19,PaynotesUi.INK,true));ui.note(card,"Loading your plan…");
        load(s->{if(!card.isAttachedToWindow())return;card.removeAllViews();card.addView(ui.text("Your payday plan",19,PaynotesUi.INK,true));JSONObject p=s.state().optJSONObject("plan");
            if(p==null){ui.note(card,"Give your spending a direction. Start with your take-home pay and the costs you want to protect.");ui.primary(card,"Build my plan",this::plan);return;}
            long left=CoachStore.remaining(s);card.addView(ui.text(Store.money(Math.abs(left)),32,PaynotesUi.INK,true));ui.note(card,(left<0?"Over your flexible spending plan":"Left in your flexible spending plan")+(s.unknown()>0?" · provisional":""));
            ui.note(card,ChronoUnit.DAYS.between(LocalDate.now(),s.next())+" days until payday · "+s.next());
            if(CoachStore.committedOverrun(s)>0)ui.note(card,"Protected costs exceeded by "+Store.money(CoachStore.committedOverrun(s))+"; deducted from the remaining plan.");
            if(s.awaiting()>0)ui.note(card,Store.money(s.awaiting())+" awaiting repayment · not available cash");
            ui.note(card,"Based on recorded payments, not your bank balance.");
            if(s.unknown()>0){android.widget.TextView review=ui.action("Match covered costs to your plan",false,()->{ui.type="Plan allocation";ui.from=s.start().atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();ui.until=LocalDate.now().plusDays(1).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli();ui.rangeLabel="This pay cycle";ui.query="";ui.category="";ui.account=null;ui.navigate("Activity");});card.addView(review);ui.gap(card,8);}
            ui.primary(card,"Review plan & goals",this::hub);
        });
    }
    void hub(){load(s->{final AlertDialog[] hub={null};LinearLayout b=box();JSONObject p=s.state().optJSONObject("plan"),g=s.state().optJSONObject("goal");
        ui.note(b,p==null?"Start with the income and costs you know.":"Flexible allocation: "+Store.money(MoneyPlan.flexible(p))+" per pay cycle\nRecorded flexible spending: "+Store.money(s.spent())+"\nRecorded committed spending: "+Store.money(s.committed())+"\nCycle: "+s.start()+" to "+s.next());
        ui.primary(b,"Income & commitments",()->{hub[0].dismiss();plan();});ui.gap(b,8);ui.primary(b,g==null?"Create a savings goal":"Review savings goal",()->{hub[0].dismiss();goal();});ui.gap(b,8);ui.primary(b,"Category limits",()->{hub[0].dismiss();limits();});ui.gap(b,8);
        if(g!=null){ui.note(b,g.optString("name")+" · "+Store.money(MoneyPlan.funded(s.state()))+" confirmed toward "+Store.money(g.optLong("amount")));ui.primary(b,"Record contribution or withdrawal",()->{hub[0].dismiss();contribution();});ui.gap(b,8);ui.primary(b,"Remove goal",()->{try{JSONObject next=LedgerDb.object(s.state().toString());next.remove("goal");next.remove("contributions");if(next.optJSONObject("plan")!=null)next.getJSONObject("plan").put("goalMonthly",0);save(s.state(),next,"Remove this goal and its local contribution log, and release its monthly allocation back into the spending plan. Your actual savings are not moved. Undo last plan change can restore this record.",()->hub[0].dismiss());}catch(JSONException e){throw new IllegalStateException(e);}});}
        ui.note(b,"Your plan stays on this phone. Under-budget spending is not automatically saved. A contribution is your confirmation, not a verified bank transfer.");
        ui.primary(b,"Export plan & corrections",()->a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").putExtra(Intent.EXTRA_TITLE,"paynotes-plan.json"),732));
        if(s.state().has("undo")){ui.gap(b,8);ui.primary(b,"Undo last plan change",()->new AlertDialog.Builder(a).setTitle("Undo last plan change?").setMessage("Restores the previous plan, goal, limits and contribution record.").setPositiveButton("Undo",(d,w)->a.mutateLedger(()->{LedgerDb db=LedgerDb.get(a);JSONObject current=CoachStore.load(db);if(!current.toString().equals(s.state().toString()))throw new IllegalStateException();CoachStore.save(db,current.optJSONObject("undo"));a.runOnUiThread(()->hub[0].dismiss());})).setNegativeButton("Cancel",null).show());}
        hub[0]=new AlertDialog.Builder(a).setTitle("Your money plan").setView(wrap(b)).setPositiveButton("Done",null).show();});}
    ScrollView wrap(LinearLayout b){ScrollView v=new ScrollView(a);v.addView(b);return v;}
    void plan(){load(s->{JSONObject old=s.state(),p=old.optJSONObject("plan");if(p==null)p=new JSONObject();LinearLayout b=box();
        ui.note(b,"Monthly take-home pay and protected costs. Use conservative amounts you can rely on. Expected income is not a confirmed bank balance.");
        String[] keys={"income","fixed","essentials","debt","reserve","goalMonthly"};String[] labels={"Take-home pay (₹)","Fixed commitments (₹)","Essential variable costs (₹)","Debt payments (₹)","Irregular costs and buffer (₹)","Goal contribution per month (₹)"};Map<String,EditText> fields=new LinkedHashMap<>();
        for(int i=0;i<keys.length;i++)fields.put(keys[i],field(b,labels[i],MoneyPlan.rupees(p.optLong(keys[i])),true));
        EditText payday=field(b,"Payday (1–31)",""+p.optInt("payday",1),true);EditText protect=field(b,"Spending you want to protect (optional)",p.optString("protect"),false);
        ui.note(b,"Avoid overlap between cost buckets. Mark payments covered by these costs as committed in Activity; all other recorded personal spending counts against the flexible plan.");
        final AlertDialog[] d={null};d[0]=dialog("Build a realistic plan",b,"Review plan",()->{try{
            JSONObject value=new JSONObject();for(String key:keys)value.put(key,MoneyPlan.amount(fields.get(key).getText().toString()));int day=Integer.parseInt(payday.getText().toString());if(day<1||day>31)throw new IllegalArgumentException("Payday must be from 1 to 31.");if(value.optLong("income")==0)throw new IllegalArgumentException("Enter your take-home pay.");value.put("payday",day).put("protect",protect.getText().toString().trim());long flexible=MoneyPlan.flexible(value);
            JSONObject next=LedgerDb.object(old.toString()).put("plan",value);save(old,next,"Flexible allocation: "+Store.money(flexible)+" per cycle."+(flexible<0?" Your commitments exceed income. Reduce a target or revise costs before relying on this plan.":"")+"\nAlready recorded flexible spending: "+Store.money(s.spent()),()->d[0].dismiss());
        }catch(JSONException e){throw new IllegalStateException(e);}});});}
    void goal(){goal(null);}
    void goal(JSONObject proposal){load(s->{JSONObject old=s.state(),g=old.optJSONObject("goal");if(g==null)g=new JSONObject();if(proposal!=null){try{g=new JSONObject().put("name",proposal.getString("name")).put("amount",proposal.getLong("amountPaise")).put("date",proposal.getString("date"));}catch(JSONException e){throw new IllegalArgumentException(e);}}LinearLayout b=box();
        EditText name=field(b,"What are you saving for?",g.optString("name"),false),amount=field(b,"Goal amount (₹)",MoneyPlan.rupees(g.optLong("amount")),true),date=field(b,"Target date (YYYY-MM-DD)",g.optString("date",LocalDate.now().plusMonths(3).toString()),false);
        ui.note(b,"One active goal. Editing keeps confirmed contributions. Use withdrawal records to correct funding; changing a target never creates savings.");
        final AlertDialog[] d={null};d[0]=dialog("A goal that fits",b,"Review goal",()->{try{String title=name.getText().toString().trim();long target=MoneyPlan.amount(amount.getText().toString());LocalDate end=LocalDate.parse(date.getText().toString().trim());if(title.isEmpty()||target==0||!end.isAfter(LocalDate.now())||end.isAfter(LocalDate.now().plusYears(50)))throw new IllegalArgumentException("Add a name, positive amount and future date within 50 years.");
            JSONObject next=LedgerDb.object(old.toString()).put("goal",new JSONObject().put("name",title).put("amount",target).put("date",end.toString()));long week=MoneyPlan.weekly(next,LocalDate.now());JSONObject p=old.optJSONObject("plan");long monthly=(week*52+11)/12;
            String fit=p==null?"Set income and commitments to check whether this fits.":monthly>p.optLong("goalMonthly")?"This exceeds your current monthly goal allocation. Extend the date or explicitly revise your plan.":"This fits the monthly goal allocation you entered; actual cash availability still needs checking.";
            save(old,next,Store.money(week)+" per week; about "+Store.money(monthly)+" per month.\n"+fit,()->d[0].dismiss());
        }catch(JSONException e){throw new IllegalStateException(e);}});});}
    void contribution(){load(s->{if(!s.state().has("goal")){goal();return;}LinearLayout b=box();EditText amount=field(b,"Amount (₹)","",true);CheckBox withdrawal=new CheckBox(a);withdrawal.setText(R.string.withdrawal_correction);b.addView(withdrawal);ui.note(b,"Record only money you actually set aside or withdrew. This does not move money or prove an increase in net wealth.");final AlertDialog[] d={null};d[0]=dialog("Record goal progress",b,"Review",()->{try{long n=MoneyPlan.amount(amount.getText().toString());if(n==0)throw new IllegalArgumentException("Enter a positive amount.");if(withdrawal.isChecked()&&n>MoneyPlan.funded(s.state()))throw new IllegalArgumentException("Withdrawal exceeds confirmed goal funding.");JSONObject next=LedgerDb.object(s.state().toString());JSONArray entries=next.optJSONArray("contributions");if(entries==null)entries=new JSONArray();entries.put(new JSONObject().put("amount",withdrawal.isChecked()?-n:n).put("time",System.currentTimeMillis()));next.put("contributions",entries);save(s.state(),next,(withdrawal.isChecked()?"Withdraw ":"Record contribution of ")+Store.money(n),()->d[0].dismiss());}catch(JSONException e){throw new IllegalStateException(e);}});});}
    void limits(){limits(null);}
    void limits(JSONObject proposal){load(s->{LinearLayout b=box();ui.note(b,"Calendar-month category limits are guardrails, not extra money. They do not increase your payday plan.");JSONObject limits=s.state().optJSONObject("limits");if(limits!=null)for(Iterator<String> it=limits.keys();it.hasNext();){String key=it.next();ui.note(b,key+": "+Store.money(s.categories().getOrDefault(key,0L))+" spent / "+Store.money(limits.optLong(key))+" limit"+(s.categories().getOrDefault(key,0L)>limits.optLong(key)?" · over limit":""));}
        Spinner category=new Spinner(a);String[] names={"Food & drink","Groceries","Shopping","Transport","Entertainment","Bills","Other"};category.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,names));b.addView(category);if(proposal!=null)for(int i=0;i<names.length;i++)if(names[i].equals(proposal.optString("name")))category.setSelection(i);EditText amount=field(b,"Monthly limit (₹; 0 removes it)",proposal==null?"":MoneyPlan.rupees(proposal.optLong("amountPaise")),true);final AlertDialog[] d={null};d[0]=dialog("Category limits",b,"Review limit",()->{try{long n=MoneyPlan.amount(amount.getText().toString());JSONObject next=LedgerDb.object(s.state().toString()),ls=next.optJSONObject("limits");if(ls==null)ls=new JSONObject();String key=category.getSelectedItem().toString();if(n==0)ls.remove(key);else ls.put(key,n);next.put("limits",ls);save(s.state(),next,key+": "+(n==0?"remove limit":Store.money(n)+" per calendar month"),()->d[0].dismiss());}catch(JSONException e){throw new IllegalStateException(e);}});});}
    void meaning(JSONObject row){
        LinearLayout b=box();boolean credit=row.optString("direction").equals("credit");
        if(credit){ui.note(b,"Link this credit to its original payment. This records a refund or repayment; it is not salary.");ui.primary(b,"Link repayment",()->link(row,"reimbursement"));ui.gap(b,8);ui.primary(b,"Link refund",()->link(row,"refund"));}
        else {ui.note(b,"Cash out: "+Store.money(row.optLong("paise"))+". A recipient name does not tell us the purpose.");EditText share=field(b,"Your personal share (₹)",MoneyPlan.rupees(row.optLong("personalSharePaise",row.optLong("paise"))),true);CheckBox committed=new CheckBox(a);committed.setText(R.string.covered_by_commitments);committed.setChecked("committed".equals(row.optString("confirmedBucket")));b.addView(committed);
            ui.primary(b,"Review personal share",()->{try{long n=MoneyPlan.amount(share.getText().toString());if(n>row.optLong("paise"))throw new IllegalArgumentException("Your share cannot exceed the payment.");confirmMeaning(row,n,committed.isChecked()?"committed":"flexible",n<row.optLong("paise")?"shared":"personal","");}catch(Exception e){toast(e.getMessage());}});ui.gap(b,8);ui.primary(b,"Own-account transfer",()->confirmMeaning(row,0,"flexible","transfer",""));ui.gap(b,8);ui.primary(b,"Credit-card bill settlement",()->confirmMeaning(row,0,"committed","settlement",""));ui.note(b,"Exclude a card settlement only when the underlying purchases are recorded separately.");}
        ui.gap(b,8);ui.primary(b,"Reset purpose correction",()->new AlertDialog.Builder(a).setTitle("Reset this correction?").setMessage("Restores captured spending treatment and unlinks credits associated with this payment.").setPositiveButton("Reset",(d,w)->a.mutateLedger(()->LedgerDb.get(a).getWritableDatabase().delete("payment_meaning","id=? OR linked=?",new String[]{row.optString("id"),row.optString("id")}))).setNegativeButton("Cancel",null).show());
        new AlertDialog.Builder(a).setTitle("What was this payment for?").setView(wrap(b)).setPositiveButton("Done",null).show();
    }
    void confirmMeaning(JSONObject row,long share,String bucket,String kind,String linked){new AlertDialog.Builder(a).setTitle("Confirm payment purpose").setMessage("Personal share: "+Store.money(share)+"\nTreatment: "+kind+" · "+bucket+"\nOriginal bank evidence stays unchanged.").setPositiveButton("Confirm",(d,w)->a.mutateLedger(()->CoachStore.meaning(LedgerDb.get(a),row.optString("id"),share,bucket,kind,linked))).setNegativeButton("Cancel",null).show();}
    void link(JSONObject row,String kind){READ.execute(()->{JSONArray rows=LedgerDb.get(a).select("direction='debit' AND source!='sample' AND category NOT IN ('Not a transaction','Payment receipt')"+(kind.equals("reimbursement")?" AND id IN (SELECT id FROM payment_meaning WHERE kind='shared')":"")+" ORDER BY time DESC LIMIT 200");a.runOnUiThread(()->{if(a.isDestroyed())return;if(rows.length()==0){toast("No eligible original payment found. For repayments, first mark the original debit as shared in Activity.");return;}String[] labels=new String[rows.length()];for(int i=0;i<labels.length;i++){JSONObject r=rows.optJSONObject(i);labels[i]=r.optString("merchant")+" · "+Store.money(r.optLong("paise"))+" · "+Instant.ofEpochMilli(r.optLong("time")).atZone(ZoneId.systemDefault()).toLocalDate();}new AlertDialog.Builder(a).setTitle("Original payment · latest 200 debits").setItems(labels,(d,w)->confirmMeaning(row,0,"flexible",kind,rows.optJSONObject(w).optString("id"))).setNegativeButton("Cancel",null).show();});});}
}
